-- Coherent SchoolOS demo seed. Auth users are intentionally not created here;
-- link profiles to real Supabase Auth accounts after invitation/sign-in.

select '11111111-1111-4111-8111-111111111111', 'M' || series, 'Route ' || series,
  (array['A. Kumar','S. Patel','R. Das','M. Ali'])[1 + (series % 4)],
  (array['K. Sharma','P. Nair','J. Roy'])[1 + (series % 3)], 42, 'Active'
from generate_series(1,30) as series on conflict(organization_id,bus_code) do nothing;
